'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const e=require('./native-fixtures-20261003.cjs').environment(),c=e.ctx;['tarot-foundation','prompt-brief','prompt-packet'].forEach(e.load);
const rows=[];for(const spreadType of ['grand','grand_nines','branches']){const cards=Array.from({length:36},(_,i)=>({id:i+1,name:'牌'+(i+1),meaning:'此處僅測牌序保留，不是個案解讀'})),chart={spreadType,expectedCount:36,cards},q='完整讀這次全部牌序',body=c.JYPromptPacket.build('lenormand',chart,q),p=c.JYPromptPacket.get(body);assert(c.JYPromptPacket.chars(body)<=12000);const d=p.readingData.sections.find(s=>s.label==='本次完整操作與牌籤作用').data;assert.equal(d.records.length,36);for(const r of d.records)assert(body.includes(r.id+'/'+r.name+'/'));if(spreadType==='branches'){const encoded=body.split('【合法全線】\n')[1].split('\n\n【')[0];assert.deepEqual(JSON.parse(encoded),JSON.parse(JSON.stringify(d.paths)));}else{const rowLen=spreadType==='grand_nines'?9:8;const sec=body.split('【大牌陣四列與尾排')[1].split('\n\n【')[0];for(let r=0;r<4;r++){const expect='第'+(r+1)+'列：'+d.records.slice(r*rowLen,r*rowLen+rowLen).map(x=>x.name).join('→');assert(sec.includes(expect),spreadType+' row '+(r+1));}if(rowLen===8)assert(sec.includes('尾排（結語，獨立讀）：'+d.records.slice(32).map(x=>x.name).join('→')));}rows.push({spreadType,cards:36,paths:d.paths.length,characters:c.JYPromptPacket.chars(body)});}
fs.writeFileSync(path.join(__dirname,'../docs/qa-single-paste27/layout-validation.json'),JSON.stringify({status:'passed',rows},null,2));console.log('36-card layouts: all three complete layouts passed.');
